<template>
  <view class="refund-page">
    <view class="hero"><view><small>ADMIN CONSOLE</small><view>退款审批</view><text>审核整单退款并跟踪支付宝处理结果</text></view><view class="hero-actions"><b>{{ total }}</b><button class="admin-home-btn" @click="backToConsole">操作列表</button></view></view>
    <view class="filters"><view class="search"><input v-model.trim="keyword" placeholder="退款单号、订单号或邮箱" @confirm="search" /><button @click="search">搜索</button></view><scroll-view scroll-x class="tabs"><text v-for="item in statuses" :key="item.value" :class="{ active: status === item.value }" @click="changeStatus(item.value)">{{ item.label }}</text></scroll-view></view>
    <view v-if="loading && !refunds.length" class="state">正在加载…</view><view v-else-if="!refunds.length" class="state">暂无退款记录</view>
    <view v-for="item in refunds" :key="item.refund_no" class="refund-card">
      <view class="head"><view><b>{{ item.username || '系统用户' }}</b><text>{{ item.email || `用户 ${item.user_id}` }}</text></view><span :class="item.status">{{ statusText(item.status) }}</span></view>
      <view class="numbers"><view><small>退款金额</small><b>¥{{ item.amount }}</b></view><view><small>收回权益</small><b>{{ item.credit_count }} 次{{ item.credit_type === 'logo' ? 'Logo' : '起名' }}</b></view></view>
      <view class="ids">订单 {{ item.order_no }}<br />退款 {{ item.refund_no }}</view><view class="reason">{{ item.reason }}</view><view v-if="item.review_note" class="review">审核：{{ item.review_note }}</view><view v-if="item.last_error" class="error">最近错误：{{ item.last_error }}</view>
      <view v-if="item.status === 'requested'" class="actions"><button @click="openAction('reject', item)">驳回</button><button class="approve" @click="openAction('approve', item)">批准退款</button></view>
      <button v-if="item.status === 'failed' || item.status === 'processing'" class="retry" @click="retry(item)">立即查退/重试</button>
    </view>
    <button v-if="refunds.length < total" class="load-more" @click="loadMore">加载更多</button>
    <view v-if="actionVisible" class="modal" @click.self="closeAction"><view><h3>{{ action === 'approve' ? '批准整单退款' : '驳回退款' }}</h3><p>{{ selected.refund_no }}</p><textarea v-model.trim="reason" maxlength="200" :placeholder="action === 'reject' ? '请输入驳回原因（必填）' : '审核备注（选填）'"></textarea><section><button @click="closeAction">取消</button><button class="confirm" :loading="submitting" @click="submitAction">确认</button></section></view></view>
  </view>
</template>

<script>
import { api } from '../../api'
import { handleAdminAuthError, requireAdminSession } from '../../utils/auth'
export default {
  data() { return { refunds: [], total: 0, page: 1, pageSize: 10, keyword: '', status: 'requested', loading: false, submitting: false, actionVisible: false, action: '', selected: null, reason: '', statuses: [{ label: '待审核', value: 'requested' }, { label: '处理中', value: 'processing' }, { label: '已退款', value: 'succeeded' }, { label: '已驳回', value: 'rejected' }, { label: '失败', value: 'failed' }, { label: '全部', value: '' }] } },
  onShow() { if (requireAdminSession()) this.load(true) },
  methods: {
    backToConsole() { uni.redirectTo({ url: '/pages/admin/index' }) },
    async load(reset = false) { if (this.loading) return; if (reset) { this.page = 1; this.refunds = [] } this.loading = true; try { const data = await api.getAdminRefunds({ page: this.page, pageSize: this.pageSize, keyword: this.keyword, status: this.status }); this.refunds = reset ? data.items : [...this.refunds, ...data.items]; this.total = data.total } catch (error) { uni.showToast({ title: error.message, icon: 'none', duration: 3000 }); handleAdminAuthError(error) } finally { this.loading = false } },
    search() { this.load(true) }, changeStatus(value) { this.status = value; this.load(true) }, loadMore() { this.page += 1; this.load(false) },
    statusText(value) { return { requested: '待审核', rejected: '已驳回', processing: '处理中', succeeded: '已退款', failed: '失败' }[value] || value },
    openAction(action, item) { this.action = action; this.selected = item; this.reason = ''; this.actionVisible = true }, closeAction() { if (this.submitting) return; this.actionVisible = false; this.selected = null },
    async submitAction() { if (this.action === 'reject' && !this.reason) { uni.showToast({ title: '请输入驳回原因', icon: 'none' }); return } this.submitting = true; try { if (this.action === 'approve') await api.approveRefund(this.selected.refund_no, this.reason); else await api.rejectRefund(this.selected.refund_no, this.reason); uni.showToast({ title: '操作完成', icon: 'success' }); this.actionVisible = false; await this.load(true) } catch (error) { uni.showToast({ title: error.message, icon: 'none', duration: 3000 }); if (!handleAdminAuthError(error)) await this.load(true) } finally { this.submitting = false } },
    async retry(item) { try { await api.retryRefund(item.refund_no); uni.showToast({ title: '已安排重试', icon: 'success' }); await this.load(true) } catch (error) { uni.showToast({ title: error.message, icon: 'none' }); handleAdminAuthError(error) } }
  }
}
</script>

<style scoped>
.refund-page{min-height:100vh;padding:28rpx 28rpx 70rpx;background:#f3f5f9}.hero{display:flex;align-items:center;justify-content:space-between;padding:34rpx;color:#fff;background:linear-gradient(135deg,#171d2d,#454b69);border-radius:29rpx}.hero small{color:#f2d586;font-size:17rpx;letter-spacing:4rpx}.hero view view{margin-top:10rpx;font-size:38rpx;font-weight:850}.hero text{display:block;margin-top:8rpx;color:#ccd0dc;font-size:20rpx}.hero-actions{display:flex;flex-direction:column;align-items:stretch;gap:10rpx}.hero-actions>b{color:#f2d586;font-size:44rpx;text-align:center}.admin-home-btn{height:54rpx;margin:0;padding:0 18rpx;color:#f5df9e;background:rgba(255,255,255,.08);border:1rpx solid rgba(245,223,158,.35);border-radius:15rpx;font-size:18rpx;line-height:52rpx}.filters,.refund-card,.state{margin-top:20rpx;padding:24rpx;background:#fff;border-radius:24rpx;box-shadow:0 10rpx 30rpx rgba(36,55,86,.05)}.search{display:flex;gap:12rpx}.search input{flex:1;height:72rpx;padding:0 18rpx;background:#f3f5f8;border-radius:16rpx;font-size:22rpx}.search button{width:110rpx;height:72rpx;margin:0;color:#fff;background:#30364d;border-radius:16rpx;font-size:21rpx;line-height:72rpx}.tabs{margin-top:17rpx;white-space:nowrap}.tabs text{display:inline-block;margin-right:10rpx;padding:11rpx 17rpx;color:#7f8797;background:#f1f3f7;border-radius:999rpx;font-size:19rpx}.tabs text.active{color:#fff;background:#6257e8}.state{padding:55rpx;text-align:center;color:#929aaa}.head{display:flex;justify-content:space-between}.head b{display:block;font-size:27rpx}.head text{display:block;margin-top:5rpx;color:#8c95a5;font-size:19rpx}.head span{padding:7rpx 13rpx;border-radius:999rpx;font-size:18rpx}.head span.requested{color:#96601a;background:#fff2d8}.head span.processing{color:#5546b8;background:#eeecff}.head span.succeeded{color:#18764c;background:#e6f7ef}.head span.failed,.head span.rejected{color:#aa4054;background:#fff0f3}.numbers{display:grid;grid-template-columns:1fr 1fr;margin-top:20rpx;padding:18rpx;background:#f6f7fa;border-radius:17rpx}.numbers view{text-align:center}.numbers small{display:block;color:#9199a8;font-size:18rpx}.numbers b{display:block;margin-top:6rpx;font-size:26rpx}.ids,.reason,.review,.error{margin-top:14rpx;color:#8e97a8;font-size:18rpx;line-height:1.55}.reason{padding:14rpx;color:#525b6e;background:#f5f6f9;border-radius:14rpx}.review{color:#645c8d}.error{color:#b24b60}.actions{display:flex;gap:13rpx;margin-top:19rpx}.actions button,.retry,.load-more{flex:1;height:66rpx;margin:0;color:#a04155;background:#fff0f3;border-radius:16rpx;font-size:21rpx;line-height:66rpx}.actions .approve,.retry{color:#fff;background:#6257e8}.retry,.load-more{width:100%;margin-top:18rpx}.load-more{color:#6257e8;background:#ebe9ff}.modal{position:fixed;z-index:100;inset:0;display:flex;align-items:flex-end;padding:30rpx;background:rgba(16,21,34,.55)}.modal>view{width:100%;padding:31rpx;background:#fff;border-radius:29rpx}.modal h3{margin:0;font-size:31rpx}.modal p{color:#8e96a5;font-size:19rpx}.modal textarea{box-sizing:border-box;width:100%;height:145rpx;padding:17rpx;background:#f4f5f8;border-radius:16rpx}.modal section{display:flex;gap:13rpx;margin-top:20rpx}.modal section button{flex:1;height:70rpx;margin:0;background:#eef0f4;border-radius:16rpx;line-height:70rpx}.modal section .confirm{color:#fff;background:#6257e8}
</style>
